#' Fit the latent RSA model family
#'
#' Writes, runs, and reads a set of second-order response surface models from
#' one model specification, the latent counterpart of the model family that
#' `RSA::RSA()` fits. Each model is generated by [create_rsa_mplus_model()]
#' with its `rsa_model`; all other arguments are shared. Compare the fitted
#' models with [compare_rsa_mplus_models()].
#'
#' @inheritParams create_rsa_mplus_model
#' @param models The models to fit, named as `rsa_model` in
#'   [create_rsa_mplus_model()]. The default is the default set of
#'   `RSA::RSA()`; `"mean"` and `"diff"` can be added. The full model is
#'   always fitted first.
#' @param start Start values for the polynomial terms. `"full"` (the default)
#'   fits the full model first and uses its estimates for all other models.
#'   `NULL` uses none. Any other value is passed to every model as `start` in
#'   [create_rsa_mplus_model()].
#' @param modelout Path of an Mplus `.inp` file that names the family. Each
#'   model is written next to it with its name appended in lower case, for
#'   example `rsa_srrr.inp` for `modelout = "rsa.inp"`, and all models read
#'   the data file `rsa.dat`. Mplus lower-cases file names, so on a
#'   case-sensitive file system (Linux, WSL) the file name of `modelout` must
#'   be lower case as well.
#' @param overwrite If `TRUE`, replace existing input and data files. If
#'   `FALSE` (the default), nothing is written when any of them exists.
#' @param Mplus_command Optional path or command used to invoke Mplus.
#'
#' @details
#' A model that fails does not stop the others. Each failure is recorded with
#' the stage at which it occurred: `"create"` (for example, a `NEW` label that
#' clashes with a label in `structural`), `"write"`, or `"run"`, where Mplus
#' reported an error. A model whose Mplus output exists keeps its parsed
#' results, so that [compare_rsa_mplus_models()] can still show what Mplus
#' estimated. A warning lists the failed models. If no model can be
#' generated, the specification itself is invalid and the first error is
#' raised.
#'
#' The restricted models are nested in the full model and share its
#' measurement model, so start values from the full model mostly save
#' iterations. When the full model fails, the other models are fitted without
#' start values.
#'
#' @return An object of class `rsa_mplus_family`, a list with
#'   * `models`: the named list of workflows (see [create_rsa_mplus_model()])
#'     in the order fitted. A model that failed in Mplus has status
#'     `"failed"`; one that could not be created is `NULL`.
#'   * `failures`: a data frame with the `model`, `stage`, and error
#'     `message` of each failed model.
#'   * `start`: the start values passed to the models other than the full
#'     model, or `NULL`.
#'   * `files`: the `input` paths, named by model, and the shared `data`
#'     path.
#' @seealso [compare_rsa_mplus_models()]
#' @export
#'
#' @examples
#' \dontrun{
#' family <- fit_rsa_mplus_family(
#'   data = dat,
#'   measurement = list(
#'     X = c("x1", "x2", "x3"),
#'     Y = c("y1", "y2", "y3"),
#'     Z = c("z1", "z2", "z3")
#'   ),
#'   modelout = "family/rsa.inp"
#' )
#' compare_rsa_mplus_models(family)
#' RSA_mplus(family$models$SRRR)
#' }
fit_rsa_mplus_family <- function(
  data,
  measurement,
  structural = NULL,
  roles = c(x = "X", y = "Y", outcome = "Z"),
  model_type = c("latent", "si_lms"),
  reliability = NULL,
  constraints = c("surface", "principal"),
  blocks = list(),
  model_extra = NULL,
  constraint_extra = NULL,
  usevariables = NULL,
  identification = c("marker", "effects", "invariance"),
  center = c("none", "pooled"),
  free_intercepts = NULL,
  models = c(
    "full", "SRRR", "SRR", "RR", "SRSQD", "SSQD", "SQD", "IA", "additive",
    "onlyx2", "onlyy2", "onlyx", "onlyy", "null"
  ),
  start = "full",
  modelout,
  overwrite = FALSE,
  Mplus_command = NULL,
  quiet = TRUE
) {
  require_rsa_mplus_namespace("tidySEM")
  require_rsa_mplus_namespace("MplusAutomation")

  models <- validate_rsa_mplus_family_models(models)
  start_full <- identical(start, "full")
  if (is.character(start) && !start_full) {
    rlang::abort(
      "`start` must be \"full\", `NULL`, or start values for `create_rsa_mplus_model()`."
    )
  }
  if (start_full && !"full" %in% models) {
    rlang::abort("`start = \"full\"` needs \"full\" in `models`.")
  }
  files <- rsa_mplus_family_files(modelout, models, overwrite)
  Mplus_command <- resolve_rsa_mplus_command(Mplus_command)

  fit <- function(rsa_model, start) {
    workflow <- NULL
    stage <- "create"
    error <- tryCatch(
      {
        workflow <- create_rsa_mplus_model(
          data = data,
          measurement = measurement,
          structural = structural,
          roles = roles,
          model_type = model_type,
          reliability = reliability,
          constraints = constraints,
          blocks = blocks,
          model_extra = model_extra,
          constraint_extra = constraint_extra,
          usevariables = usevariables,
          identification = identification,
          center = center,
          free_intercepts = free_intercepts,
          rsa_model = rsa_model,
          start = start,
          quiet = quiet
        )
        stage <- "write"
        # Existing files were checked for the whole family beforehand.
        workflow <- write_rsa_mplus_model(
          workflow,
          modelout = files$input[[rsa_model]],
          dataout = files$data,
          overwrite = TRUE,
          quiet = quiet
        )
        stage <- "run"
        workflow <- run_rsa_mplus_model(
          workflow,
          Mplus_command = Mplus_command,
          quiet = quiet
        )
        NULL
      },
      error = function(e) e
    )
    if (is.null(error)) {
      return(list(workflow = workflow, failure = NULL))
    }

    # Mplus errors include untrustworthy standard errors, which still leave
    # estimates and a log-likelihood worth reporting.
    if (identical(stage, "run") && file.exists(workflow$files$output)) {
      workflow <- tryCatch(
        read_rsa_mplus_model(workflow, quiet = quiet),
        error = function(e) workflow
      )
    }
    if (!is.null(workflow)) {
      workflow$status <- "failed"
    }
    list(
      workflow = workflow,
      failure = data.frame(
        model = rsa_model,
        stage = stage,
        message = conditionMessage(error)
      )
    )
  }

  fits <- list()
  if ("full" %in% models) {
    fits$full <- fit("full", if (start_full) NULL else start)
  }
  if (start_full) {
    start <- rsa_mplus_family_start(fits$full$workflow)
  }
  for (rsa_model in setdiff(models, "full")) {
    fits[[rsa_model]] <- fit(rsa_model, start)
  }

  workflows <- lapply(fits, `[[`, "workflow")
  failures <- do.call(
    rbind,
    c(
      list(data.frame(
        model = character(),
        stage = character(),
        message = character()
      )),
      lapply(fits, `[[`, "failure")
    )
  )
  rownames(failures) <- NULL

  if (all(failures$stage[match(models, failures$model)] %in% "create")) {
    rlang::abort(c(
      "No model of the family could be generated.",
      x = failures$message[[1]]
    ))
  }
  if (nrow(failures) > 0L) {
    rlang::warn(c(
      sprintf(
        "%d of %d models failed:",
        nrow(failures),
        length(models)
      ),
      stats::setNames(
        sprintf(
          "`%s` (%s): %s",
          failures$model,
          failures$stage,
          failures$message
        ),
        rep("x", nrow(failures))
      ),
      if (start_full && is.null(start)) {
        c(i = "The other models were fitted without start values.")
      }
    ))
  }

  structure(
    list(
      models = workflows,
      failures = failures,
      start = start,
      files = files
    ),
    class = "rsa_mplus_family"
  )
}

#' @export
print.rsa_mplus_family <- function(x, ...) {
  cat("<rsa_mplus_family>\n")
  cat("Models:", paste(names(x$models), collapse = ", "), "\n")
  if (nrow(x$failures) > 0L) {
    cat(
      "Failed:",
      paste(
        sprintf("%s (%s)", x$failures$model, x$failures$stage),
        collapse = ", "
      ),
      "\n"
    )
  }
  if (!is.null(x$start)) {
    cat("Start values:", rsa_mplus_family_format_start(x$start), "\n")
  }
  if (!is.null(x$files$data)) {
    cat("Data:", x$files$data, "\n")
  }
  cat("Compare the models with `compare_rsa_mplus_models()`.\n")
  invisible(x)
}

rsa_mplus_family_format_start <- function(start) {
  if (inherits(start, "rsa_mplus_workflow")) {
    return("from a fitted workflow")
  }
  if (inherits(start, "rsa_mplus")) {
    start <- start$coefficients
  }
  if (!is.numeric(start) || is.null(names(start))) {
    return("supplied")
  }
  start <- start[names(start) != "b0"]
  paste(
    sprintf("%s = %s", names(start), vapply(start, rsa_mplus_number, "")),
    collapse = ", "
  )
}

validate_rsa_mplus_family_models <- function(
  models,
  call = rlang::caller_env()
) {
  valid <- names(rsa_mplus_model_restrictions)
  if (!is.character(models) || length(models) == 0L || anyNA(models)) {
    rlang::abort(
      "`models` must name at least one model of the RSA family.",
      call = call
    )
  }
  unknown <- setdiff(models, valid)
  if (length(unknown) > 0L) {
    rlang::abort(
      c(
        sprintf(
          "Unknown model%s in `models`: %s.",
          if (length(unknown) == 1L) "" else "s",
          paste(sprintf("`%s`", unknown), collapse = ", ")
        ),
        i = sprintf(
          "The family has %s.",
          paste(sprintf("`%s`", valid), collapse = ", ")
        )
      ),
      call = call
    )
  }
  if (anyDuplicated(models)) {
    rlang::abort("`models` must name each model once.", call = call)
  }
  c(intersect("full", models), setdiff(models, "full"))
}

rsa_mplus_family_files <- function(
  modelout,
  models,
  overwrite,
  call = rlang::caller_env()
) {
  if (
    !is.character(modelout) ||
      length(modelout) != 1L ||
      is.na(modelout) ||
      !grepl("\\.inp$", modelout, ignore.case = TRUE)
  ) {
    rlang::abort(
      "`modelout` must be a single path with an `.inp` extension.",
      call = call
    )
  }
  modelout <- normalizePath(modelout, mustWork = FALSE)
  if (!dir.exists(dirname(modelout))) {
    rlang::abort(
      sprintf("Output directory does not exist: `%s`.", dirname(modelout)),
      call = call
    )
  }
  stem <- sub("\\.inp$", "", modelout, ignore.case = TRUE)
  # Mplus lower-cases the names of the files it reads and writes. A name such
  # as `rsa_SRRR.inp` is then not found on a case-sensitive file system.
  files <- list(
    input = stats::setNames(paste0(stem, "_", tolower(models), ".inp"), models),
    data = paste0(stem, ".dat")
  )

  paths <- c(unname(files$input), files$data)
  existing <- paths[file.exists(paths)]
  if (length(existing) > 0L && !isTRUE(overwrite)) {
    rlang::abort(
      sprintf(
        "Refusing to overwrite existing file%s: %s. Use `overwrite = TRUE` to replace %s.",
        if (length(existing) == 1L) "" else "s",
        paste(sprintf("`%s`", existing), collapse = ", "),
        if (length(existing) == 1L) "it" else "them"
      ),
      call = call
    )
  }
  files
}

# Estimates of the full model, or NULL when it has none to offer.
rsa_mplus_family_start <- function(workflow) {
  if (is.null(workflow) || is.null(workflow$results)) {
    return(NULL)
  }
  tryCatch(
    RSA_mplus(workflow, plot = FALSE)$coefficients,
    error = function(e) NULL
  )
}

#' Compare the models of the latent RSA family
#'
#' Ranks fitted models of the RSA family by AICc, as `RSA::aictab()` does, and
#' tests each restricted model against the full model with a scaled
#' likelihood-ratio test, as `RSA::compare()` does. Mplus reports no
#' chi-square, CFI, RMSEA, or SRMR for models with `XWITH`, so the comparison
#' rests on the log-likelihoods.
#'
#' @param x An `rsa_mplus_family` from [fit_rsa_mplus_family()], or a named
#'   list of fitted workflows (see [rsa_mplus_workflow()]). Each workflow's
#'   model is taken from the workflow, or otherwise from its name.
#' @param tolerance Largest log-likelihood by which a model may exceed a model
#'   it is nested in before this is flagged. The default absorbs the error of
#'   the numerical integration.
#' @param boundary Distance, in standard deviations of the latent predictors,
#'   beyond which a ridge or valley line is flagged as lying outside the data.
#' @param reference The model against which the likelihood-ratio tests are
#'   run. The default tests every restricted model against the full model.
#'   With another model, for example `"a5zero"` or `"additive"`, only the
#'   models nested in it are tested.
#'
#' @details
#' Model selection follows Schönbrodt's *Testing fit patterns with polynomial
#' regression models*: AICc is primary and the likelihood-ratio tests are
#' secondary. AICc is `-2*LL + 2*k + 2*k*(k + 1)/(N - k - 1)`, with `k` all
#' free parameters, including the measurement model, and `N` the number of
#' observations. Akaike weights are computed over the converged models, and
#' the evidence ratio is the weight of the best model divided by the weight of
#' each model, as in `RSA::aictab()`.
#'
#' The likelihood-ratio test uses the Satorra-Bentler scaled difference of
#' the MLR log-likelihoods. With `p0` parameters and scaling correction
#' factor `c0` in the restricted model and `p1` and `c1` in the full model,
#' the difference test scaling correction is
#' `cd = (p0*c0 - p1*c1)/(p0 - p1)` and the test statistic is
#' `-2*(LL0 - LL1)/cd` on `p1 - p0` degrees of freedom. A `cd` that is not
#' positive leaves the test undefined; it is flagged and its statistic and
#' p-value are `NA`. Without a scaling correction factor in the output, as
#' under `ESTIMATOR = ML`, `c = 1` and the test is the ordinary
#' likelihood-ratio test.
#'
#' `flags` collects what needs attention:
#' * The run failed, did not converge, or Mplus printed errors or warnings.
#'   Their text is in the `messages` attribute. Models without a
#'   log-likelihood are listed last and excluded from the ranking.
#' * A model fits better, by more than `tolerance`, than a model it is nested
#'   in. Then one of them did not reach its optimum, usually the larger one,
#'   and a warning is raised. The nesting follows the restrictions of
#'   [create_rsa_mplus_model()].
#' * The ridge or valley line of `"SRRR"`, `"SRR"`, `"SRSQD"`, or `"SSQD"`,
#'   `Y = S*X + C`, lies more than `boundary` standard deviations from the
#'   centroid of the latent X and Y, or the rotated models `"SRRR"` and
#'   `"SRSQD"` have `b5` at 0 (to three decimals). These models are not
#'   defined at `b5 = 0`. When the surface has no such line, they drift
#'   towards it and mimic a plane with a far-away line, and `C` and `S` cannot
#'   be interpreted.
#' * `cd <= 0` in the likelihood-ratio test.
#'
#' `R2` is the R-square of the outcome factor as printed by Mplus, and `NA`
#' when Mplus prints none (it is part of the standardized output).
#'
#' @return A data frame of class `rsa_mplus_comparison` with one row per
#'   model, ordered by AICc: `model`, `k`, `LL`, `AICc`, `delta_AICc`,
#'   `weight` (Akaike weight), `cum_weight`, `evidence_ratio`, the test
#'   against the `reference` model (`lrt_df`, `lrt_cd`, `lrt_chisq`, `lrt_p`),
#'   `R2`,
#'   `converged`, and `flags`. The attribute `messages` holds the Mplus
#'   errors and warnings and the failures of [fit_rsa_mplus_family()], with
#'   columns `model`, `type`, and `message`.
#' @seealso [fit_rsa_mplus_family()]
#' @export
#'
#' @examples
#' \dontrun{
#' comparison <- compare_rsa_mplus_models(family)
#' comparison
#' attr(comparison, "messages")
#' }
compare_rsa_mplus_models <- function(
  x,
  tolerance = 0.01,
  boundary = 3,
  reference = "full"
) {
  if (
    !is.character(reference) ||
      length(reference) != 1L ||
      !reference %in% names(rsa_mplus_model_restrictions)
  ) {
    rlang::abort("`reference` must name one model of the RSA family.")
  }
  if (!is.numeric(tolerance) || length(tolerance) != 1L || is.na(tolerance)) {
    rlang::abort("`tolerance` must be a single number.")
  }
  if (!is.numeric(boundary) || length(boundary) != 1L || !(boundary > 0)) {
    rlang::abort("`boundary` must be a single positive number.")
  }

  failures <- NULL
  if (inherits(x, "rsa_mplus_family")) {
    failures <- x$failures
    x <- x$models
  }
  if (!is.list(x) || length(x) == 0L || inherits(x, "rsa_mplus_workflow")) {
    rlang::abort(
      "`x` must be an `rsa_mplus_family` or a named list of fitted workflows."
    )
  }
  rsa_models <- vapply(
    seq_along(x),
    function(i) rsa_mplus_comparison_model(x[[i]], names(x)[i]),
    character(1)
  )
  if (anyDuplicated(rsa_models)) {
    rlang::abort(sprintf(
      "Each model may appear once; `%s` is repeated.",
      rsa_models[anyDuplicated(rsa_models)]
    ))
  }

  summaries <- Map(rsa_mplus_fit_summary, x, rsa_models)
  fits <- do.call(rbind, lapply(summaries, `[[`, "fit"))
  messages <- do.call(rbind, lapply(summaries, `[[`, "messages"))
  if (!is.null(failures) && nrow(failures) > 0L) {
    messages <- rbind(
      data.frame(
        model = failures$model,
        type = "failure",
        message = sprintf("%s: %s", failures$stage, failures$message)
      ),
      messages
    )
    fits$status[fits$model %in% failures$model & !fits$converged] <- "failed"
  }
  rownames(fits) <- NULL
  rownames(messages) <- NULL

  # Without the full model the default comparison has no tests; a reference
  # that was asked for must be there.
  if (!identical(reference, "full") && !reference %in% rsa_models) {
    rlang::abort(sprintf(
      "The reference model `%s` is not among the fitted models.",
      reference
    ))
  }

  rsa_mplus_comparison_table(fits, messages, tolerance, boundary, reference)
}

#' @export
print.rsa_mplus_comparison <- function(x, digits = 3, ...) {
  cat("<rsa_mplus_comparison>\n")
  shown <- as.data.frame(x)
  shown$converged <- NULL
  shown$flags <- NULL
  shown$k <- as.integer(shown$k)
  shown$lrt_df <- as.integer(shown$lrt_df)
  for (column in c("LL", "AICc", "delta_AICc", "lrt_chisq")) {
    shown[[column]] <- round(shown[[column]], 2L)
  }
  for (column in c("weight", "cum_weight", "lrt_cd", "R2")) {
    shown[[column]] <- round(shown[[column]], digits)
  }
  shown$evidence_ratio <- ifelse(
    is.na(shown$evidence_ratio),
    NA_character_,
    formatC(shown$evidence_ratio, digits = digits, format = "g")
  )
  shown$lrt_p <- ifelse(
    is.na(shown$lrt_p),
    NA_character_,
    format.pval(shown$lrt_p, digits = digits, eps = 0.001)
  )
  print(shown, row.names = FALSE, na.print = "")

  flagged <- nzchar(x$flags)
  if (any(flagged)) {
    cat("\nFlags:\n")
    cat(sprintf("  %s: %s\n", x$model[flagged], x$flags[flagged]), sep = "")
  }
  messages <- attr(x, "messages")
  if (!is.null(messages) && nrow(messages) > 0L) {
    cat("Mplus messages: see `attr(x, \"messages\")`.\n")
  }
  invisible(x)
}

# Models in which each model of the family is directly nested, following the
# restrictions in `rsa_mplus_model_restrictions`. A model is nested in all of
# its ancestors along these edges. The rotated ridge models are undefined at
# b5 = 0, so the models without curvature are nested in them only through SRR
# and SSQD; "onlyx2" lies only on the edge of SRRR (S -> infinity) and is
# therefore left out, whereas "onlyy2" is SRSQD with S = 0. "addx2",
# "addy2", "noIA", and "a5zero" are not in the RSA package; "a5zero" nests
# SRR and IA.
rsa_mplus_model_parents <- list(
  full = character(),
  noIA = "full",
  a5zero = "full",
  addx2 = "noIA",
  addy2 = "noIA",
  SRRR = "full",
  SRR = c("SRRR", "a5zero"),
  RR = "SRR",
  SRSQD = "SRRR",
  SSQD = c("SRR", "SRSQD"),
  SQD = c("RR", "SSQD"),
  IA = c("full", "a5zero"),
  additive = c("IA", "SRR", "addx2", "addy2"),
  mean = c("RR", "additive"),
  diff = c("SSQD", "additive"),
  onlyx2 = c("full", "addx2"),
  onlyy2 = c("SRSQD", "addy2"),
  onlyx = c("onlyx2", "additive"),
  onlyy = c("onlyy2", "additive"),
  null = c("SQD", "mean", "diff", "onlyx", "onlyy")
)

rsa_mplus_model_ancestors <- function(rsa_model) {
  ancestors <- character()
  queue <- rsa_mplus_model_parents[[rsa_model]]
  while (length(queue) > 0L) {
    ancestors <- union(ancestors, queue)
    queue <- setdiff(
      unlist(rsa_mplus_model_parents[queue], use.names = FALSE),
      ancestors
    )
  }
  ancestors
}

rsa_mplus_comparison_model <- function(workflow, name) {
  if (!is.null(workflow) && !inherits(workflow, "rsa_mplus_workflow")) {
    rlang::abort(
      "`x` must be an `rsa_mplus_family` or a named list of fitted workflows."
    )
  }
  rsa_model <- workflow$spec$rsa_model
  if (is.null(rsa_model)) {
    rsa_model <- name
  }
  if (
    is.null(rsa_model) ||
      !rsa_model %in% names(rsa_mplus_model_restrictions)
  ) {
    rlang::abort(
      "Name each workflow by its model, e.g. `list(full = ..., SRRR = ...)`."
    )
  }
  rsa_model
}

# One row of fit information and the Mplus messages of a workflow.
rsa_mplus_fit_summary <- function(workflow, rsa_model) {
  fit <- data.frame(
    model = rsa_model,
    n = NA_real_,
    k = NA_real_,
    LL = NA_real_,
    scaling = NA_real_,
    R2 = NA_real_,
    b5 = NA_real_,
    ridge_distance = NA_real_,
    converged = FALSE,
    status = "not run"
  )
  messages <- data.frame(
    model = character(),
    type = character(),
    message = character()
  )

  results <- workflow$results
  if (is.null(results) && !is.null(workflow$mplus$results)) {
    results <- workflow$mplus$results
  }
  if (is.null(results)) {
    return(list(fit = fit, messages = messages))
  }

  summary_value <- function(name) {
    value <- results$summaries[[name]]
    if (length(value) == 0L) NA_real_ else as.numeric(value[[1]])
  }
  fit$n <- summary_value("Observations")
  fit$k <- summary_value("Parameters")
  fit$LL <- summary_value("LL")
  fit$scaling <- summary_value("LLCorrectionFactor")

  collapse <- function(x) {
    vapply(x, function(lines) paste(trimws(lines), collapse = " "), "")
  }
  warnings <- collapse(results$warnings)
  errors <- collapse(results$errors)
  messages <- data.frame(
    model = rep(rsa_model, length(errors) + length(warnings)),
    type = rep(c("error", "warning"), c(length(errors), length(warnings))),
    message = unname(c(errors, warnings))
  )

  stopped <- any(grepl(
    "DID NOT TERMINATE NORMALLY|NO CONVERGENCE",
    errors,
    ignore.case = TRUE
  ))
  fit$converged <- is.finite(fit$LL) && is.finite(fit$k) && !stopped
  fit$status <- if (fit$converged) "ok" else "not converged"

  roles <- as.list(workflow$spec$roles)
  metadata <- workflow$spec$metadata
  role <- function(name, label) {
    value <- c(roles[[name]], metadata[[label]])
    if (length(value) == 0L) NA_character_ else toupper(value[[1]])
  }
  outcome <- role("outcome", "outcome")
  parameters <- results$parameters$unstandardized
  pick <- function(header, param) {
    if (is.null(parameters) || length(param) == 0L || is.na(param)) {
      return(NA_real_)
    }
    hits <- which(
      toupper(parameters$paramHeader) %in% toupper(header) &
        toupper(parameters$param) == toupper(param)
    )
    if (length(hits) == 0L) NA_real_ else as.numeric(parameters$est[[hits[[1]]]])
  }

  r2 <- results$parameters$r2
  if (!is.null(r2) && !is.na(outcome)) {
    hits <- which(toupper(r2$param) == outcome)
    if (length(hits) > 0L) {
      fit$R2 <- as.numeric(r2$est[[hits[[1]]]])
    }
  }

  derived <- names(rsa_mplus_model_restrictions[[rsa_model]]$derived)
  if ("c" %in% derived && !is.na(outcome)) {
    fit$b5 <- pick(
      paste0(outcome, ".ON"),
      c(metadata$pred_y2, "YS")[[1]]
    )
    predictors <- c(x = role("x", "pred_x"), y = role("y", "pred_y"))
    fit$ridge_distance <- rsa_mplus_ridge_distance(
      c = pick("New.Additional.Parameters", "C"),
      s = if ("s" %in% derived) pick("New.Additional.Parameters", "S") else 1,
      means = vapply(
        predictors,
        function(p) {
          mean <- pick(c("Means", "Intercepts"), p)
          if (is.na(mean)) 0 else mean
        },
        numeric(1)
      ),
      variances = vapply(
        predictors,
        function(p) pick(c("Variances", "Residual.Variances"), p),
        numeric(1)
      )
    )
  }

  list(fit = fit, messages = messages)
}

# Distance of the line Y = s*X + c from the centroid of the latent X and Y,
# in units of their pooled standard deviation. The latent means are 0 unless
# the factors are centred on a shared origin.
rsa_mplus_ridge_distance <- function(c, s, means, variances) {
  sd <- sqrt(mean(variances))
  offset <- s * means[["x"]] + c - means[["y"]]
  abs(offset) / sqrt(1 + s^2) / sd
}

# Ranks the fits by AICc and adds the scaled likelihood-ratio test against the
# full model and the flags. `fits` has one row per model with `model`, `n`,
# `k`, `LL`, `scaling`, `R2`, `b5`, `ridge_distance`, `converged`, and
# `status`.
rsa_mplus_comparison_table <- function(
  fits,
  messages,
  tolerance,
  boundary,
  reference = "full"
) {
  usable <- fits$converged
  n <- unique(fits$n[usable])
  if (length(n) > 1L) {
    rlang::warn(sprintf(
      "The models were fitted to different numbers of observations (%s); their AICc and likelihood-ratio tests are not comparable.",
      paste(n, collapse = ", ")
    ))
  }

  k <- fits$k
  aicc <- ifelse(
    usable & fits$n - k - 1 > 0,
    -2 * fits$LL + 2 * k + 2 * k * (k + 1) / (fits$n - k - 1),
    NA_real_
  )
  ranked <- is.finite(aicc)
  delta <- aicc - suppressWarnings(min(aicc[ranked]))
  weight <- exp(-delta / 2)
  weight <- weight / sum(weight[ranked])

  # Scaled difference test against the reference model (Satorra & Bentler,
  # 2001), for the models nested in it. Without the reference among the
  # converged models there is no test.
  scaling <- ifelse(is.na(fits$scaling), 1, fits$scaling)
  full <- which(fits$model == reference & usable)
  lrt_df <- lrt_cd <- lrt_chisq <- lrt_p <- rep(NA_real_, nrow(fits))
  if (length(full) == 1L) {
    nested <- vapply(
      fits$model,
      function(model) reference %in% rsa_mplus_model_ancestors(model),
      logical(1)
    )
    tested <- usable & nested & k < k[full]
    lrt_df[tested] <- k[full] - k[tested]
    lrt_cd[tested] <- (k[tested] * scaling[tested] - k[full] * scaling[full]) /
      (k[tested] - k[full])
    valid <- which(tested & lrt_cd > 0)
    lrt_chisq[valid] <- -2 * (fits$LL[valid] - fits$LL[full]) / lrt_cd[valid]
    lrt_p[valid] <- stats::pchisq(
      lrt_chisq[valid],
      df = lrt_df[valid],
      lower.tail = FALSE
    )
  }

  flags <- replicate(nrow(fits), character(), simplify = FALSE)
  add_flag <- function(rows, text) {
    for (i in seq_along(rows)) {
      flags[[rows[[i]]]] <<- c(flags[[rows[[i]]]], text[[i]])
    }
  }

  failed <- which(fits$status != "ok")
  add_flag(failed, fits$status[failed])
  for (type in c("error", "warning")) {
    counts <- table(factor(
      messages$model[messages$type == type],
      levels = fits$model
    ))
    rows <- which(counts > 0L)
    add_flag(
      rows,
      sprintf(
        "%d Mplus %s%s",
        counts[rows],
        type,
        ifelse(counts[rows] == 1L, "", "s")
      )
    )
  }

  violations <- character()
  for (i in which(usable)) {
    ancestors <- intersect(
      rsa_mplus_model_ancestors(fits$model[[i]]),
      fits$model[usable]
    )
    for (ancestor in ancestors) {
      gain <- fits$LL[[i]] - fits$LL[fits$model == ancestor]
      if (gain > tolerance) {
        add_flag(i, sprintf("LL above %s by %.3f", ancestor, gain))
        violations <- c(
          violations,
          sprintf(
            "`%s` fits better than `%s`, which nests it, by %.3f.",
            fits$model[[i]],
            ancestor,
            gain
          )
        )
      }
    }
  }
  if (length(violations) > 0L) {
    rlang::warn(c(
      "A model fits better than a model it is nested in:",
      stats::setNames(violations, rep("x", length(violations))),
      i = "One of them did not reach its optimum, usually the larger model. Refit it, for example with start values from the smaller one or more random starts."
    ))
  }

  rotated <- fits$model %in% c("SRRR", "SRSQD")
  at_zero <- which(usable & rotated & abs(fits$b5) < 5e-4)
  add_flag(at_zero, rep("b5 = 0", length(at_zero)))
  outside <- which(usable & fits$ridge_distance > boundary)
  add_flag(
    outside,
    sprintf("line %.1f SD from the data", fits$ridge_distance[outside])
  )
  undefined <- which(!is.na(lrt_cd) & lrt_cd <= 0)
  add_flag(undefined, rep("cd <= 0", length(undefined)))

  comparison <- data.frame(
    model = fits$model,
    k = k,
    LL = fits$LL,
    AICc = aicc,
    delta_AICc = ifelse(ranked, delta, NA_real_),
    weight = ifelse(ranked, weight, NA_real_),
    cum_weight = NA_real_,
    evidence_ratio = ifelse(ranked, exp(delta / 2), NA_real_),
    lrt_df = lrt_df,
    lrt_cd = lrt_cd,
    lrt_chisq = lrt_chisq,
    lrt_p = lrt_p,
    R2 = fits$R2,
    converged = fits$converged,
    flags = vapply(flags, paste, character(1), collapse = "; ")
  )

  rows <- c(which(ranked)[order(aicc[ranked])], which(!ranked))
  comparison <- comparison[rows, , drop = FALSE]
  top <- seq_len(sum(ranked))
  comparison$cum_weight[top] <- cumsum(comparison$weight[top])
  # As in `RSA::aictab()`, the best model has no evidence ratio.
  if (any(ranked)) {
    comparison$evidence_ratio[[1]] <- NA_real_
  }
  rownames(comparison) <- NULL

  structure(
    comparison,
    messages = messages,
    class = c("rsa_mplus_comparison", "data.frame")
  )
}
